/** Demo-Konfiguration für einen Agenten (Fallback: Muster-Firma). */
function ch_demo_cfg(string $plan): array {
  $d = CH_DEMO[$plan] ?? ['company'=>'Muster GmbH','tone'=>'freundlich-professionell','lang'=>'de','greeting'=>'Hallo! Ich bin der Demo-Agent. Was kann ich für dich tun?','chips'=>['Was kannst du?','Wie funktioniert die Einrichtung?'],
    'kb'=>"Muster GmbH, Musterstraße 1, 10115 Berlin. Öffnungszeiten Mo–Fr 9–17 Uhr. Kontakt: info@muster.de. Leistungen: Beratung, Service, Support."];
  return $d + ['widget_key'=>null,'widget_domain'=>'','widget_on'=>0];
}
